components.css:
.ds-btn-primary { display: inline-flex; justify-content: center; align-items: center; width: 100%; background: #215E70; color: #F7FBFC; border: 0; border-radius: 14px; padding: 14px 18px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 17px; font-weight: 600; cursor: pointer; }
.ds-btn-primary:hover { opacity: 0.86; }
.ds-btn-primary:focus-visible { outline: 2px solid #215E70; outline-offset: 3px; }
.ds-btn-primary:active { opacity: 0.86; }

.ds-btn-quiet { display: inline-flex; justify-content: center; align-items: center; width: 100%; background: #F7FBFC; color: #1E2C31; border: 1px solid rgba(30, 44, 49, 0.12); border-radius: 14px; padding: 14px 18px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 17px; font-weight: 600; cursor: pointer; }
.ds-btn-quiet:hover { color: rgba(30, 44, 49, 0.7); }
.ds-btn-quiet:focus-visible { outline: 2px solid #215E70; outline-offset: 3px; }
.ds-btn-quiet:active { color: rgba(30, 44, 49, 0.7); }

.ds-card { width: 220px; padding: 12px; background: #F7FBFC; color: #1E2C31; border: 1px solid rgba(30, 44, 49, 0.08); border-radius: 16px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.ds-card-photo { height: 132px; border-radius: 12px; }
.ds-card-name { margin: 8px 0 4px; font-size: 17px; font-weight: 600; line-height: 1.3; }
.ds-card-amount { display: flex; align-items: center; gap: 8px; margin: 0; font-size: 15px; }
.ds-card-dot { width: 12px; height: 12px; border-radius: 50%; border: 1px solid rgba(30, 44, 49, 0.12); }
.ds-card:hover { border-color: #215E70; }
.ds-card:focus-visible { outline: 2px solid #215E70; outline-offset: 3px; }

.ds-field { display: flex; align-items: center; gap: 8px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #4E6068; font-size: 15px; }
.ds-swatch { width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(30, 44, 49, 0.12); flex: none; }
.ds-field-copy { display: grid; gap: 4px; flex: 1; }
.ds-input { font: inherit; font-size: 17px; color: #1E2C31; background: #F7FBFC; border: 1px solid rgba(30, 44, 49, 0.12); border-radius: 12px; padding: 10px 12px; }
.ds-input:hover { border-color: rgba(30, 44, 49, 0.28); }
.ds-input:focus-visible { outline: 2px solid #215E70; outline-offset: 2px; border-color: #215E70; }

.ds-nav { display: flex; align-items: center; gap: 8px; background: #E6EEF0; color: #1E2C31; padding: 8px 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.ds-nav-title { margin: 0; flex: 1; font-size: 34px; font-weight: 600; line-height: 1.15; letter-spacing: -0.02em; }
.ds-nav-add { width: 44px; height: 44px; border-radius: 14px; border: 0; background: transparent; color: #215E70; font-size: 28px; line-height: 1; cursor: pointer; }
.ds-nav-add:hover { background: rgba(33, 94, 112, 0.1); }
.ds-nav-add:focus-visible { outline: 2px solid #215E70; outline-offset: 2px; }

.ds-badge { display: inline-flex; align-items: center; background: #215E70; color: #F7FBFC; border-radius: 999px; padding: 3px 7px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 12px; font-weight: 600; }
.ds-badge:hover { opacity: 0.86; }
.ds-badge:focus-visible { outline: 2px solid #215E70; outline-offset: 2px; }

.ds-sampler { position: relative; height: 180px; border-radius: 16px; border: 1px solid rgba(30, 44, 49, 0.08); overflow: hidden; }
.ds-ring { position: absolute; left: 58%; top: 46%; width: 28px; height: 28px; margin: -14px 0 0 -14px; border: 2px solid #fff; border-radius: 50%; box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45); }
.ds-ring::before, .ds-ring::after { content: ""; position: absolute; background: #fff; }
.ds-ring::before { left: 12px; top: 6px; width: 1px; height: 12px; }
.ds-ring::after { left: 6px; top: 12px; width: 12px; height: 1px; }
.ds-loupe { position: absolute; left: 58%; top: calc(46% - 46px); width: 56px; height: 56px; margin: -28px 0 0 -28px; border-radius: 50%; border: 2px solid #fff; background: #C6A15B; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18); }
.ds-sampler:hover .ds-ring { border-color: #F7FBFC; }
.ds-sampler:focus-visible { outline: 2px solid #215E70; outline-offset: 3px; }
